defmodule JoobQ.ArgumentsTest do
  use ExUnit.Case, async: true

  alias JoobQ.Batches

  @secret "acme-secret"

  defp refused(fun) do
    error = assert_raise ArgumentError, fun
    refute error.message =~ @secret
    error.message
  end

  test "options that are not a keyword list are refused by their kind, never printed" do
    bad = [{"context", %{"tenant" => @secret}}]

    assert refused(fn -> Batches.body([{"q", "t"}], on_success: {"q", "cb", %{}, [@secret]}) end) =~
             "keyword list"

    assert refused(fn -> Batches.body([{"q", "t"}], on_failure: {"q", "cb", %{}, bad}) end) =~
             "keyword list"

    assert refused(fn -> Batches.body([{"q", "t", %{}, bad}], []) end) =~ "keyword list"
    assert refused(fn -> JoobQ.enqueue_many([{"q", "t", %{}, bad}]) end) =~ "keyword list"

    for opts <- [@secret, bad, [{:name, :x} | @secret]] do
      assert refused(fn -> JoobQ.enqueue("q", "t", %{}, opts) end) =~ "keyword list"
      assert refused(fn -> JoobQ.start_workflow("w", nil, opts) end) =~ "keyword list"
      assert refused(fn -> JoobQ.rate_limit("k", 1, 1, opts) end) =~ "keyword list"
      assert refused(fn -> JoobQ.create_batch([{"q", "t"}], opts) end) =~ "keyword list"
    end
  end

  test "job lists that are not proper lists are refused without walking into them" do
    improper = [{"q", "t", %{"k" => @secret}} | @secret]
    assert refused(fn -> Batches.body(improper, []) end) =~ "1 to 1000"
    assert refused(fn -> JoobQ.enqueue_many(improper) end) =~ "a list"
    assert refused(fn -> JoobQ.create_batch(improper, name: :nowhere) end) =~ "1 to 1000"
  end
end
